#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 int maxValueOfCoins(vector<vector<int>>& piles,int k){vector<int>dp(k+1,-1000000000);dp[0]=0;
  for(auto&pile:piles){vector<int>ndp=dp;int sum=0;for(int take=1;take<=(int)pile.size()&&take<=k;++take){sum+=pile[take-1];
    for(int j=take;j<=k;++j)if(dp[j-take]>=0)ndp[j]=max(ndp[j],dp[j-take]+sum);
   }dp.swap(ndp);
  }return dp[k];
 }
};
